inline double normp(uint64_t p){auto it=NC.find(p);if(it!=NC.end())return it->second;int a[12];for(int i=0;i<12;i++)a[i]=(p>>(3*i))&7;double z=0;for(int i=0;i<12;i++)for(int j=0;j<12;j++)z+=a[i]*G[i][j]*a[j];NC.emplace(p,z);return z;}
