void recspl(uint64_t pc,const State&c,int i,int rem,State&a,int e,double beta,double &L){if(i==12){if(rem)return;State b{};for(int k=0;k<12;k++)b[k]=c[k]-a[k];uint64_t pa=pack(a),pb=pack(b);if(pa>pb)return;splitcount++;if(splitcount%10000000ull==0)cerr<<"progress splits "<<splitcount<<" memo "<<MEM.size()<<" calls "<<calls<<"\n"<<flush;uint64_t ca=canon(a),cb=canon(b);double d=dlt(pa,pb,pc),term;if(pa!=pb)term=-beta*d+solve(ca,e+1)+solve(cb,e+1);else term=-beta*d+lse(2*solve(ca,e+1),solve(ca,e+2))-log(2.);L=lse(L,term);return;}int tail=0;for(int k=i+1;k<12;k++)tail+=c[k];for(int v=max(0,rem-tail);v<=min<int>(c[i],rem);v++){a[i]=v;recspl(pc,c,i+1,rem-v,a,e,beta,L);}a[i]=0;}
double solve(uint64_t pc,int e){Key K{pc,(uint8_t)e};auto it=MEM.find(K);if(it!=MEM.end())return it->second;calls++;if(tot(pc)==1)return MEM.emplace(K,0.).first->second;State c=unpack(pc),a{};double L=-INFINITY,beta=ldexp(beta0,e);recspl(pc,c,0,tot(pc)/2,a,e,beta,L);MEM.emplace(K,L);return L;}
